import * as crypto from "crypto";

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string>;
  handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }>;
}

interface UserRecord {
  id: string;
  email: string;
  passwordHash: string;
  role?: string;
  failedAttempts: number;
  lockedUntil: number;
}

interface RateEntry {
  count: number;
  windowStart: number;
  blockedUntil: number;
}

const MAX_ATTEMPTS = 5;
const LOCKOUT_MS = 15 * 60 * 1000;
const RATE_LIMIT = 10;
const RATE_WINDOW_MS = 60_000;
const RATE_BLOCK_MS = 60_000;

export class AuthService implements IAuthService {
  private users = new Map<string, UserRecord>();
  private rateMap = new Map<string, RateEntry>();

  constructor(seedUsers: Array<{ email: string; password: string; role?: string }> = []) {
    for (const u of seedUsers) {
      crypto.scrypt(u.password, crypto.randomBytes(16).toString("hex"), 64, (err, derived) => {
        if (err) return;
        this.users.set(u.email, {
          id: crypto.randomUUID(),
          email: u.email,
          passwordHash: `${16}:${crypto.randomBytes(16).toString("hex")}:${derived.toString("hex")}`,
          role: u.role,
          failedAttempts: 0,
          lockedUntil: 0,
        });
      });
    }
  }

  async hashPassword(password: string): Promise<string> {
    const salt = crypto.randomBytes(16);
    const derived: Buffer = await new Promise((res, rej) =>
      crypto.scrypt(password, salt, 64, (e, d) => (e ? rej(e) : res(d)))
    );
    return `scrypt:${salt.toString("hex")}:${derived.toString("hex")}`;
  }

  async verifyPassword(password: string, hash: string): Promise<boolean> {
    try {
      const [scheme, saltHex, keyHex] = hash.split(":");
      if (scheme !== "scrypt") return false;
      const salt = Buffer.from(saltHex, "hex");
      const expected = Buffer.from(keyHex, "hex");
      const derived: Buffer = await new Promise((res, rej) =>
        crypto.scrypt(password, salt, expected.length, (e, d) => (e ? rej(e) : res(d)))
      );
      return crypto.timingSafeEqual(derived, expected);
    } catch {
      return false;
    }
  }

  async generateToken(
    payload: { id: string; email: string; role?: string },
    secret: string
  ): Promise<string> {
    const header = { alg: "HS256", typ: "JWT" };
    const now = Math.floor(Date.now() / 1000);
    const body = { ...payload, iat: now, exp: now + 3600 };
    const b64 = (o: object) =>
      Buffer.from(JSON.stringify(o)).toString("base64url");
    const data = `${b64(header)}.${b64(body)}`;
    const sig = crypto.createHmac("sha256", secret).update(data).digest("base64url");
    return `${data}.${sig}`;
  }

  private checkRate(ip: string): boolean {
    const now = Date.now();
    const e = this.rateMap.get(ip);
    if (!e || now - e.windowStart > RATE_WINDOW_MS) {
      this.rateMap.set(ip, { count: 1, windowStart: now, blockedUntil: 0 });
      return true;
    }
    if (e.blockedUntil > now) return false;
    e.count += 1;
    if (e.count > RATE_LIMIT) {
      e.blockedUntil = now + RATE_BLOCK_MS;
      return false;
    }
    return true;
  }

  async handleLogin(request: {
    email?: string;
    password?: string;
    ip?: string;
  }): Promise<{ status: number; body: any }> {
    const ip = request.ip ?? "unknown";
    if (!this.checkRate(ip)) {
      return { status: 429, body: { error: "Too many requests. Try again later." } };
    }
    const email = request.email?.trim().toLowerCase();
    const password = request.password ?? "";
    if (!email || !password) {
      return { status: 400, body: { error: "Email and password are required." } };
    }
    const user = this.users.get(email);
    const now = Date.now();
    if (!user) {
      return { status: 401, body: { error: "Invalid credentials." } };
    }
    if (user.lockedUntil > now) {
      return { status: 423, body: { error: "Account temporarily locked." } };
    }
    const ok = await this.verifyPassword(password, user.passwordHash);
    if (!ok) {
      user.failedAttempts += 1;
      if (user.failedAttempts >= MAX_ATTEMPTS) {
        user.lockedUntil = now + LOCKOUT_MS;
        user.failedAttempts = 0;
      }
      return { status: 401, body: { error: "Invalid credentials." } };
    }
    user.failedAttempts = 0;
    user.lockedUntil = 0;
    const token = await this.generateToken(
      { id: user.id, email: user.email, role: user.role },
      process.env.JWT_SECRET ?? "default-secret"
    );
    return { status: 200, body: { token, user: { id: user.id, email: user.email, role: user.role } } };
  }

  async register(email: string, password: string, role?: string): Promise<void> {
    this.users.set(email.trim().toLowerCase(), {
      id: crypto.randomUUID(),
      email: email.trim().toLowerCase(),
      passwordHash: await this.hashPassword(password),
      role,
      failedAttempts: 0,
      lockedUntil: 0,
    });
  }
}

