import crypto from 'node:crypto';

export interface IAuthService {
  hashPassword(password: string): Promise<string>;
  verifyPassword(password: string, hash: string): Promise<boolean>;
  generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string>;
  handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }>;
}

interface StoredUser {
  id: string;
  email: string;
  passwordHash: string;
  role: string;
  failedAttempts: number;
  lockedUntil: number;
}

const PBKDF2_ITERATIONS = 210_000;
const KEY_LEN = 64;
const DIGEST = 'sha512';
const ACCESS_TOKEN_TTL_SEC = 900; // 15 minutes
const MAX_ATTEMPTS = 5;
const LOCKOUT_MS = 15 * 60 * 1000;
const RATE_WINDOW_MS = 60_000;
const RATE_MAX = 10;

export class AuthService implements IAuthService {
  private users = new Map<string, StoredUser>();
  private rateBuckets = new Map<string, { count: number; resetAt: number }>();

  constructor(seedUsers: Array<{ email: string; password: string; role?: string }> = []) {
    for (const u of seedUsers) {
      this.users.set(u.email.toLowerCase(), {
        id: crypto.randomUUID(),
        email: u.email.toLowerCase(),
        passwordHash: crypto
          .pbkdf2Sync(u.password, u.email.toLowerCase(), PBKDF2_ITERATIONS, KEY_LEN, DIGEST)
          .toString('hex'),
        role: u.role ?? 'user',
        failedAttempts: 0,
        lockedUntil: 0,
      });
    }
  }

  async hashPassword(password: string): Promise<string> {
    const salt = crypto.randomBytes(16);
    const derived = await crypto.pbkdf2(password, salt, PBKDF2_ITERATIONS, KEY_LEN, DIGEST);
    return `pbkdf2$${DIGEST}$${PBKDF2_ITERATIONS}$${salt.toString('hex')}$${derived.toString('hex')}`;
  }

  async verifyPassword(password: string, hash: string): Promise<boolean> {
    const parts = hash.split('$');
    if (parts.length !== 5 || parts[0] !== 'pbkdf2') return false;
    const digest = parts[1];
    const iterations = parseInt(parts[2], 10);
    const salt = Buffer.from(parts[3], 'hex');
    const expected = Buffer.from(parts[4], 'hex');
    if (!Number.isFinite(iterations) || iterations < 1 || expected.length !== KEY_LEN) return false;
    const actual = await crypto.pbkdf2(password, salt, iterations, expected.length, digest);
    return expected.length === actual.length && crypto.timingSafeEqual(expected, actual);
  }

  async generateToken(payload: { id: string; email: string; role?: string }, secret: string): Promise<string> {
    if (typeof secret !== 'string' || secret.length < 32) {
      throw new Error('Secret must be at least 32 characters');
    }
    const header = { alg: 'HS256', typ: 'JWT' };
    const now = Math.floor(Date.now() / 1000);
    const body = { ...payload, iat: now, exp: now + ACCESS_TOKEN_TTL_SEC, jti: crypto.randomUUID() };
    const enc = (o: object) => Buffer.from(JSON.stringify(o)).toString('base64url');
    const signingInput = `${enc(header)}.${enc(body)}`;
    const sig = crypto.createHmac('sha256', secret).update(signingInput).digest('base64url');
    return `${signingInput}.${sig}`;
  }

  private checkRateLimit(ip: string): boolean {
    const now = Date.now();
    const bucket = this.rateBuckets.get(ip);
    if (!bucket || now >= bucket.resetAt) {
      this.rateBuckets.set(ip, { count: 1, resetAt: now + RATE_WINDOW_MS });
      return true;
    }
    bucket.count += 1;
    return bucket.count <= RATE_MAX;
  }

  async handleLogin(request: { email?: string; password?: string; ip?: string }): Promise<{ status: number; body: any }> {
    try {
      const ip = request.ip ?? 'unknown';
      if (!this.checkRateLimit(ip)) {
        return { status: 429, body: { error: 'RATE_LIMITED', message: 'Too many requests. Try again later.' } };
      }
      const email = (request.email ?? '').trim().toLowerCase();
      const password = request.password ?? '';
      if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) || typeof password !== 'string' || password.length < 8) {
        return { status: 400, body: { error: 'INVALID_CREDENTIALS', message: 'Email and password are required.' } };
      }
      const user = this.users.get(email);
      const now = Date.now();
      const generic = { error: 'INVALID_CREDENTIALS', message: 'Invalid email or password.' };

      if (user && user.lockedUntil > now) {
        return { status: 423, body: { error: 'ACCOUNT_LOCKED', message: 'Account temporarily locked.' } };
      }

      const valid = user ? await this.verifyPassword(password, user.passwordHash) : false;
      if (!user || !valid) {
        if (user) {
          user.failedAttempts += 1;
          if (user.failedAttempts >= MAX_ATTEMPTS) {
            user.lockedUntil = now + LOCKOUT_MS;
            user.failedAttempts = 0;
          }
        }
        return { status: 401, body: generic };
      }

      user.failedAttempts = 0;
      user.lockedUntil = 0;
      const secret = process.env.JWT_SECRET ?? '';
      if (secret.length < 32) {
        return { status: 500, body: { error: 'INTERNAL_SERVER_ERROR', message: 'Authentication unavailable.' } };
      }
      const token = await this.generateToken({ id: user.id, email: user.email, role: user.role }, secret);
      return {
        status: 200,
        body: {
          token,
          tokenType: 'Bearer',
          expiresIn: ACCESS_TOKEN_TTL_SEC,
          user: { id: user.id, email: user.email, role: user.role },
        },
      };
    } catch (err) {
      console.error(JSON.stringify({ level: 'error', msg: 'login_failure', err: String(err) }));
      return { status: 500, body: { error: 'INTERNAL_SERVER_ERROR', message: 'An unexpected error occurred.' } };
    }
  }
}

